/* AUTO-GENERATED from Comptia-Study-Library/esri_gis.html quizQuestions. */
/* Domains re-aligned to the official Esri ArcGIS Pro Foundation (EAPF_2025) blueprint: */
/* D1 Mapping & Visualization | D2 Data Management | D3 Performing Analysis | D4 Layouts & Sharing. */
window.QUESTION_POOLS = window.QUESTION_POOLS || {};
window.QUESTION_POOLS['arcgis'] = [
  { q: "Which of the following is NOT a piece every GIS dataset must have?", opts: ["Geometry", "Attributes", "Spatial reference", "Symbology"], answer: 3, domain: 'D2', exp: "Geometry, attributes, and spatial reference are the three required pieces. Symbology is a presentation choice — the same data can be drawn many ways." },
  { q: "A shapefile (.shp) has which of these limits?", opts: ["No size limit, 64-char field names", "2 GB size, 10-char field names", "4 GB size, 32-char field names", "1 TB size, full field names"], answer: 1, domain: 'D2', exp: "Shapefile = 2 GB max per .shp/.dbf, 10-character field names, no native time data. File geodatabase removes these limits." },
  { q: "What does the OBJECTID field represent?", opts: ["A user-editable primary key", "A field for storing object descriptions", "A system-managed unique ID for each row", "The geometry of the feature"], answer: 2, domain: 'D2', exp: "OBJECTID is auto-generated and managed by ArcGIS. Never edit or delete it; joins and selections rely on it." },
  { q: "Which data type best represents elevation across an entire watershed?", opts: ["Vector polygon", "Vector point cloud", "Raster (DEM)", "Annotation"], answer: 2, domain: 'D2', exp: "Continuous phenomena (elevation, temperature, rainfall) are best stored as raster. A DEM is the standard product." },
  { q: "A GeoJSON file specifies its coordinates in which CRS?", opts: ["Web Mercator (EPSG 3857)", "WGS 84 (EPSG 4326)", "NAD 83 (EPSG 4269)", "UTM zone of origin"], answer: 1, domain: 'D2', exp: "The GeoJSON spec (RFC 7946) mandates WGS 84 / EPSG 4326. Other CRSs are not part of the standard." },
  { q: "You need to enforce that road feature classes only contain values \"Highway\", \"Arterial\", or \"Local\" in their TYPE field. What do you use?", opts: ["Subtype", "Domain", "Attribute rule", "Relationship class"], answer: 1, domain: 'D2', exp: "A coded-value domain restricts a field to a controlled vocabulary, preventing typos and standardizing input." },
  { q: "Which is true about a join in ArcGIS Pro?", opts: ["It modifies the original feature class permanently", "It is temporary until you export to a new dataset", "It requires a relationship class", "It only works between two rasters"], answer: 1, domain: 'D2', exp: "Joins are virtual until you export. The original feature class is untouched; the join lives only in your project." },
  { q: "A multipoint geometry represents:", opts: ["A line that touches itself", "One feature row containing many disconnected points", "A single 3D point", "A point with a Z value"], answer: 1, domain: 'D2', exp: "Multipart geometries let one feature row hold multiple disjoint geometries. Hawaii as one polygon feature with many island parts is a classic example." },
  { q: "You have a 4-band orthoimagery raster. Which bands are typically present?", opts: ["Red, Green, Blue, Alpha", "Red, Green, Blue, Near-Infrared", "Hue, Saturation, Value, Alpha", "Pan, Red, Blue, Thermal"], answer: 1, domain: 'D2', exp: "Standard 4-band orthoimagery is R/G/B/NIR. The NIR band drives NDVI and vegetation analyses." },
  { q: "Which file is NOT a required sidecar of a shapefile?", opts: [".shp", ".shx", ".dbf", ".gdb"], answer: 3, domain: 'D2', exp: ".shp + .shx + .dbf are required; .prj is recommended for CRS. .gdb is a separate format (file geodatabase)." },
  { q: "NDVI is calculated as:", opts: ["(Red - NIR) / (Red + NIR)", "(NIR - Red) / (NIR + Red)", "(Green - Red) / (Green + Red)", "(NIR - Blue) / (NIR + Blue)"], answer: 1, domain: 'D3', exp: "NDVI = (NIR - Red) / (NIR + Red). Healthy vegetation reflects NIR strongly and absorbs Red, producing values near 1." },
  { q: "What happens to file size if you halve a raster's cell size?", opts: ["File size halves", "File size stays the same", "File size roughly quadruples", "File size doubles"], answer: 2, domain: 'D2', exp: "Halving cell size (linear) quadruples cell COUNT (area), so file size grows by ~4x. The trade-off for sharper detail is much larger files." },
  { q: "A continuous raster is best symbolized with:", opts: ["Unique values", "A color ramp (stretched)", "Heatmap", "Single symbol"], answer: 1, domain: 'D1', exp: "Continuous data (elevation, temperature) suits a stretched color ramp. Unique values fit discrete/thematic rasters like land-cover classes." },
  { q: "Which is the modern Esri vector container, supporting domains and attribute rules?", opts: ["Shapefile", "Feature class in a file geodatabase", "DBF", "CSV with WKT"], answer: 1, domain: 'D2', exp: "Feature classes in a geodatabase support domains, subtypes, attribute rules, and have no 2 GB shapefile limit." },
  { q: "KML is best for:", opts: ["Editable enterprise GIS", "Viewing on a Google Earth-style 3D globe", "High-precision survey CAD", "Topology validation"], answer: 1, domain: 'D1', exp: "KML/KMZ is the Google Earth format. Good for 3D globe display; attribute support is limited compared to feature classes." },
  { q: "A vector polygon feature class would best represent:", opts: ["Daily rainfall surface", "Census tract boundaries", "GPS track of a hike", "Photo locations of wildlife"], answer: 1, domain: 'D2', exp: "Census tract boundaries are discrete areas with sharp edges — classic polygon vector. Rainfall is continuous (raster); a GPS track is a polyline; photo locations are points." },
  { q: "Two adjacent polygons share an edge in a feature class with topology. What rule is being enforced?", opts: ["Features must overlap", "Features must not overlap", "Features must have the same OBJECTID", "Features must use the same symbology"], answer: 1, domain: 'D2', exp: "\"Must not overlap\" is a common topology rule for parcel/admin-boundary data. Topology rules catch digitizing errors at the data layer." },
  { q: "Which statement about GCS vs PCS is correct?", opts: ["Both use meters as units", "GCS uses degrees; PCS uses meters or feet", "PCS data can never be measured", "GCS data is always more accurate"], answer: 1, domain: 'D2', exp: "Geographic CRS use angular units (degrees); Projected CRS use linear units (meters, feet). Measure distances and areas in a PCS." },
  { q: "What is the EPSG code for WGS 84?", opts: ["3857", "4269", "4326", "4267"], answer: 2, domain: 'D2', exp: "WGS 84 = EPSG 4326. Web Mercator = 3857, NAD 83 = 4269, NAD 27 = 4267." },
  { q: "You load two layers and they don't line up. Most likely cause?", opts: ["Different OBJECTID counters", "Different datums / CRS without a datum transformation", "Different file formats", "Different symbology"], answer: 1, domain: 'D2', exp: "Mismatched datums (e.g., NAD 27 vs NAD 83) without a transformation can offset data by 100+ meters in the lower 48. Set the project CRS and check transformations." },
  { q: "Web Mercator is widely used because:", opts: ["It preserves area perfectly", "It is the basemap default for Google/OSM/AGOL web maps", "It uses no datum", "It is required by FGDC"], answer: 1, domain: 'D1', exp: "Web Mercator (EPSG 3857) is the de facto web tile standard. It is conformal but badly distorts area at high latitudes." },
  { q: "You receive a feature class with no .prj file and unknown CRS. The coordinates fall within UTM zone 14N. You should:", opts: ["Run Project to convert to UTM 14N", "Run Define Projection and set it to UTM 14N", "Re-digitize the data", "Change the field types"], answer: 1, domain: 'D2', exp: "Define Projection sets the CRS LABEL without changing coordinates. Project would transform the coordinates — wrong if the data is already in UTM 14N but mislabeled." },
  { q: "A conformal projection preserves:", opts: ["Area", "Local angles and shape", "Distance from one point", "Direction from the equator"], answer: 1, domain: 'D2', exp: "Conformal projections (Mercator, Lambert Conformal Conic) preserve local angles and shape. Equal-area projections preserve area, equidistant preserve distance." },
  { q: "For a US-wide choropleth map of population density, which projection is most appropriate?", opts: ["Web Mercator", "Albers Equal Area Conic", "UTM Zone 1N", "Conformal Lambert (Hawaii)"], answer: 1, domain: 'D2', exp: "Choropleths need an equal-area projection so area-based statistics (density) compare fairly. Albers Equal Area Conic is the lower-48 standard." },
  { q: "A UTM zone is how many degrees of longitude wide?", opts: ["1", "6", "10", "15"], answer: 1, domain: 'D2', exp: "UTM divides the world into 60 zones of 6 degrees each. Within a zone, distance accuracy is roughly 1 part in 2,500." },
  { q: "WKID in ArcGIS Pro is essentially:", opts: ["A shapefile field", "The EPSG code", "A Python module", "A geodatabase ID"], answer: 1, domain: 'D2', exp: "WKID (Well-Known ID) is Esri's term for the EPSG code, an industry-standard numeric CRS identifier." },
  { q: "A geoid represents:", opts: ["A perfect sphere model of Earth", "The gravitational \"sea level\" surface", "A flat-Earth approximation", "The Mercator projection grid"], answer: 1, domain: 'D2', exp: "The geoid is the gravity-equipotential surface approximating mean sea level — used as the reference for elevation. It is bumpy, not smooth." },
  { q: "WGS 84 (EPSG 4326) coordinates are in:", opts: ["Meters", "Decimal degrees", "Feet", "Radians"], answer: 1, domain: 'D2', exp: "WGS 84 is a geographic CRS with angular units — decimal degrees of latitude and longitude." },
  { q: "You define projection on data with the WRONG CRS. What happens?", opts: ["Coordinates are converted to the new CRS", "Coordinates stay the same but the CRS label becomes a lie, causing future operations to misplace the data", "A backup is automatically created", "ArcGIS Pro refuses the operation"], answer: 1, domain: 'D2', exp: "Define Projection only changes the label; geometry coordinates are untouched. A wrong label produces silent disaster in every subsequent operation." },
  { q: "NAD 27 and NAD 83 can differ by approximately how much in the lower 48 states?", opts: ["A few millimeters", "A few centimeters", "Up to ~100 meters", "Several kilometers"], answer: 2, domain: 'D2', exp: "The shift between NAD 27 and NAD 83 reaches roughly 100 m in parts of the lower 48 — large enough to ruin any analysis if data is mixed without a transformation." },
  { q: "Which projection is used for high-accuracy mapping within a single US state?", opts: ["Web Mercator", "State Plane Coordinate System (SPCS)", "WGS 84", "Mollweide"], answer: 1, domain: 'D2', exp: "State Plane (often NAD 83-based) is designed for centimeter-level accuracy within each state, with different projection families (Lambert vs Transverse Mercator) chosen to fit the state's shape." },
  { q: "You can look up unknown EPSG codes at:", opts: ["epsg.io", "arcgis.com", "wikipedia.org/wiki/projection", "crsregistry.com"], answer: 0, domain: 'D2', exp: "epsg.io is the community standard for searching and converting EPSG/WKID entries." },
  { q: "In ArcGIS Pro, when adding a layer with a different CRS than the map, what happens?", opts: ["The layer fails to load", "The layer is projected on the fly to match the map frame", "You must run Project first", "The map switches to the layer's CRS"], answer: 1, domain: 'D2', exp: "Pro projects layers on-the-fly. This is convenient for display, but analysis is most reliable when all inputs share one PCS." },
  { q: "A datum and an ellipsoid differ how?", opts: ["They are synonyms", "Datum anchors the ellipsoid to real-world reference points; the ellipsoid is just a mathematical shape", "Ellipsoid is for elevation only", "Datum is for raster, ellipsoid for vector"], answer: 1, domain: 'D2', exp: "The ellipsoid is an idealized math model of Earth's shape. The datum ties that ellipsoid to specific reference points on the ground." },
  { q: "Which is NOT one of the five must-have map elements?", opts: ["Title", "Legend", "Scale bar", "Hyperlink to source URL"], answer: 3, domain: 'D4', exp: "Title, legend, scale bar, north arrow, and neat line/credits are the standard required elements. Source attribution is required but is text, not a clickable link." },
  { q: "A skewed-data choropleth where most counties have low values and a few are very high. Which classification handles this best?", opts: ["Equal Interval", "Natural Breaks (Jenks)", "Standard Deviation", "Single symbol"], answer: 1, domain: 'D1', exp: "Natural Breaks finds gaps in the data and breaks there, handling skewed distributions far better than Equal Interval (which leaves everything in one bin)." },
  { q: "Quantile classification ensures:", opts: ["Equal value range per bin", "Equal feature count per bin", "Equal area per bin", "Equal color per bin"], answer: 1, domain: 'D1', exp: "Quantile distributes features evenly across bins. Good for rankings; can put very different values into the same bin." },
  { q: "For ordered data ranging from low to high, which palette type is appropriate?", opts: ["Qualitative", "Sequential", "Diverging", "Categorical"], answer: 1, domain: 'D1', exp: "Sequential ramps (light to dark of one hue) communicate order. Diverging suits midpoint data; qualitative/categorical suit unordered categories." },
  { q: "A diverging palette is best when:", opts: ["Data has no order", "Data has a meaningful midpoint like zero", "Data is binary", "Data is missing"], answer: 1, domain: 'D1', exp: "Diverging palettes (two hues meeting at a neutral middle) emphasize deviation from a meaningful midpoint — gain/loss, above/below average." },
  { q: "Smart Mapping in ArcGIS Online:", opts: ["Auto-runs spatial joins on import", "Inspects field data type and distribution and suggests defensible symbology", "Designs your map layout", "Pre-publishes your map"], answer: 1, domain: 'D1', exp: "Smart Mapping reads your data and proposes appropriate classification + palette defaults. A great starting point for choropleths." },
  { q: "Heatmaps are best for:", opts: ["Comparing exact counts between cities", "Showing density patterns in point data", "Mapping country boundaries", "Displaying continuous elevation"], answer: 1, domain: 'D1', exp: "Heatmaps visualize density estimation from points. They show where features cluster but should NOT be used to report exact counts." },
  { q: "Annotation differs from labels in that annotation:", opts: ["Is generated automatically every redraw", "Is fixed text stored in the geodatabase", "Has no font properties", "Is invisible at print scale"], answer: 1, domain: 'D1', exp: "Annotation features are stored as actual database records with locked positions. Labels are dynamic and reposition each redraw." },
  { q: "For a map with 18 distinct land-cover categories, you should:", opts: ["Use Unique Values with 18 colors", "Use Heatmap", "Consolidate to fewer categories or use a different visualization", "Use a sequential ramp"], answer: 2, domain: 'D1', exp: "Past about 7 categories the legend becomes unreadable. Combine related classes (deciduous/evergreen → forest) or split into multiple maps." },
  { q: "ColorBrewer is best known for:", opts: ["3D modeling", "Color-blind-safe palettes for thematic mapping", "Open data hosting", "Generating heatmaps"], answer: 1, domain: 'D1', exp: "ColorBrewer publishes ramps designed for cartographic clarity and color-blind accessibility. Built into ArcGIS Pro and AGOL Smart Mapping." },
  { q: "The visual hierarchy of a map should:", opts: ["Treat every element equally", "Make the most important features the most visually prominent", "Center on the legend", "Avoid contrast"], answer: 1, domain: 'D1', exp: "Good cartography uses size, color, and sharpness to make the focal data pop. The reader's eye finds the answer in seconds." },
  { q: "Which map element can usually be OMITTED on a small inset map where north is clearly up?", opts: ["Title", "Scale bar", "North arrow", "Legend"], answer: 2, domain: 'D4', exp: "A north arrow can be omitted on small insets where orientation is obvious. Title and scale should usually stay; legend depends on what is shown." },
  { q: "A graphic scale bar is preferred over a written ratio (e.g., \"1:24,000\") because:", opts: ["It is required by ISO", "It resizes correctly when the map is reproduced at a different size", "It saves paper", "Written scales are inaccurate"], answer: 1, domain: 'D4', exp: "Graphic scale bars scale with the map. A written ratio becomes wrong if the map is reduced or enlarged." },
  { q: "A red-green diverging palette is risky because:", opts: ["It uses too many colors", "About 8% of men are red-green color blind and cannot distinguish the endpoints", "Red and green look the same on every monitor", "It is copyrighted"], answer: 1, domain: 'D1', exp: "Red-green color blindness affects ~8% of men. Use blue/orange diverging or test with a simulator instead." },
  { q: "Graduated colors require which data type?", opts: ["Categorical", "Numeric", "Text", "Boolean"], answer: 1, domain: 'D1', exp: "Graduated colors map a numeric value to a color ramp via a classification method. For categorical fields, use Unique Values instead." },
  { q: "A heatmap on a count-by-state choropleth would be:", opts: ["A best practice", "Misleading — heatmap is for point density, not polygon counts", "A required map element", "A type of legend"], answer: 1, domain: 'D1', exp: "Heatmaps interpret point density. Counts joined to polygons are choropleth territory — use Graduated Colors with a per-area normalization." },
  { q: "Standard Deviation classification is appropriate when:", opts: ["The data has a meaningful mean and \"above/below average\" matters", "You want equal counts per bin", "You want the same color for every feature", "There is no variance"], answer: 0, domain: 'D1', exp: "Standard Deviation classification highlights deviation from the mean — best when above/below average is the story." },
  { q: "In geoprocessing, what happens to the original input data after a tool runs?", opts: ["It is deleted", "It is left untouched; the tool writes a NEW output dataset", "It is renamed", "It is overwritten"], answer: 1, domain: 'D3', exp: "Geoprocessing is file-based: outputs are new datasets and originals are preserved. This is the safety net of the geoprocessing model." },
  { q: "You need all features in layer A that fall WITHIN polygons of layer B, preserving A's attributes only. Use:", opts: ["Intersect", "Clip", "Union", "Spatial Join"], answer: 1, domain: 'D3', exp: "Clip is the cookie-cutter: keep parts of A inside B; only A's attributes are retained. Intersect would also carry B's attributes." },
  { q: "Union differs from Intersect in that Union:", opts: ["Keeps only the overlap", "Outputs the FULL area of both inputs, marked by source layer", "Drops attributes", "Is only for rasters"], answer: 1, domain: 'D3', exp: "Union preserves every part of both inputs — overlap and non-overlap. Intersect keeps only the overlap." },
  { q: "Buffer with a dissolve option does:", opts: ["Hard-deletes original features", "Merges overlapping buffer rings into single features", "Adds attributes to the input", "Projects the result to Web Mercator"], answer: 1, domain: 'D3', exp: "The Dissolve option in Buffer merges overlapping buffer geometries into a single feature, useful for \"how much area is within X meters of these features?\"" },
  { q: "Spatial Join with one-to-many output:", opts: ["Always summarizes to one row per A feature", "Creates a row in the output for every spatial match between A and B", "Requires identical OBJECTIDs", "Erases A's attributes"], answer: 1, domain: 'D3', exp: "One-to-many spatial join emits one row per match. One-to-one (default) collapses matches with a summary stat like mean or count." },
  { q: "You need to find all schools within 500 meters of any park. Which combination works best?", opts: ["Buffer parks by 500m, then Select By Location (intersect) on schools", "Define Projection on parks", "Project rasters to NAD 27", "Reclassify the schools layer"], answer: 0, domain: 'D3', exp: "Buffer the parks 500 m, then Select By Location → intersect to grab the schools that fall inside any buffer." },
  { q: "Map Algebra is used in:", opts: ["Vector overlay", "Raster cell-by-cell math", "Symbology classification", "Schema design"], answer: 1, domain: 'D3', exp: "Map Algebra performs arithmetic and logical operations on raster cell values. NDVI is a classic example." },
  { q: "Reclassify is most useful for:", opts: ["Converting continuous raster values into discrete classes", "Adding new fields", "Reprojecting a raster", "Building a model"], answer: 0, domain: 'D3', exp: "Reclassify maps ranges of cell values to new values — e.g., elevation 0-500 → 1 (\"low\"), 500-1500 → 2 (\"medium\"), 1500+ → 3 (\"high\")." },
  { q: "Hillshade is created from:", opts: ["A polygon layer of mountains", "A DEM and a chosen sun azimuth/altitude", "A satellite image", "An attribute table"], answer: 1, domain: 'D3', exp: "Hillshade simulates sun-illumination on a DEM. The azimuth (compass direction) and altitude (angle above horizon) control the shading." },
  { q: "Zonal Statistics outputs:", opts: ["A new raster of the same cell size as the value raster", "A summary table of stats (mean, sum, count, max) per zone", "A buffer polygon", "A KML file"], answer: 1, domain: 'D3', exp: "Zonal Statistics computes summary stats of a value raster within zones defined by another. The classic use: mean elevation per county." },
  { q: "Slope (in degrees) is computed from a DEM and produces:", opts: ["A vector polygon layer", "A raster where each cell value is the slope at that location", "A point feature class", "A table"], answer: 1, domain: 'D3', exp: "Slope is a raster — each output cell holds the slope value (in degrees or percent) computed from elevation neighbors." },
  { q: "A geoprocessing Environment setting \"Mask\" does:", opts: ["Hides feature symbology", "Restricts processing to cells inside the mask layer", "Encrypts the output", "Increases parallelism"], answer: 1, domain: 'D3', exp: "Mask is a raster environment limiting analysis to cells inside a polygon/raster. Useful for \"run nationally, mask to one state.\"" },
  { q: "ModelBuilder is preferable to ArcPy when:", opts: ["You need conditional loops over thousands of inputs", "You want a visual workflow to document and share with non-coders", "You need to call external REST APIs", "You need GitHub source control"], answer: 1, domain: 'D3', exp: "ModelBuilder shines for visual workflows and team documentation. ArcPy is preferred for loops, branches, and integration with non-Esri tools." },
  { q: "The Near tool returns:", opts: ["A buffer of fixed width", "For each input feature, the nearest feature in another layer and the distance to it", "A spatial join", "A topology error report"], answer: 1, domain: 'D3', exp: "Near (and Generate Near Table) finds the nearest feature in a comparison layer for each input feature and records distance + ID." },
  { q: "Erase removes area in B from A. Which inputs are involved?", opts: ["Two rasters", "Two point feature classes only", "Two polygon layers (or point/line erased by polygon)", "Two attribute tables"], answer: 2, domain: 'D3', exp: "Erase subtracts area of B (typically polygons) from A. Used for excluding study-area zones or removing infill." },
  { q: "Output Coordinate System environment matters because:", opts: ["It controls font sizes", "When inputs have different CRSs, this controls the CRS of the output (otherwise the first input's CRS is used)", "It encrypts the output", "It changes attribute field types"], answer: 1, domain: 'D3', exp: "If inputs differ in CRS, setting Output Coordinate System explicitly avoids surprise. Otherwise tools may default to the first input's CRS." },
  { q: "Select By Attributes accepts what query language?", opts: ["Regex", "SQL", "Arcade only", "Python comprehensions"], answer: 1, domain: 'D3', exp: "Select By Attributes uses SQL. Examples: POPULATION > 50000 AND STATE = 'TX'." },
  { q: "ArcGIS Online is best described as:", opts: ["A desktop installation", "A cloud SaaS GIS platform for hosting, sharing, and serving maps and data", "A spatial database", "A Python module"], answer: 1, domain: 'D4', exp: "AGOL is Esri's cloud SaaS platform. ArcGIS Pro is the desktop counterpart." },
  { q: "You publish a web map at \"Org\" sharing. A student outside your org tries to open it and sees broken layers. The likely cause is:", opts: ["The web map needs to be at \"Public\" AND every layer in it must be shared at \"Public\" too", "The student needs ArcGIS Pro", "The basemap is offline", "The student lacks ArcPy"], answer: 0, domain: 'D4', exp: "An app/map's audience can't exceed the layers inside it. Share every layer at the widest level the audience needs." },
  { q: "A Hosted Feature Layer is:", opts: ["Pre-rendered raster tiles", "AGOL-hosted vector data, editable from the web and queryable via REST", "A printed map", "A Pro project file"], answer: 1, domain: 'D4', exp: "Hosted Feature Layers are AGOL-managed vector layers. Editable and REST-queryable; storage uses credits." },
  { q: "A Hosted Tile Layer differs from a Hosted Feature Layer in that the tile layer:", opts: ["Is editable from the web", "Is pre-rendered raster (or vector) tiles, fast but not directly editable", "Stores no symbology", "Cannot be added to a web map"], answer: 1, domain: 'D4', exp: "Tile layers are pre-rendered. They're fast for big audiences but rebuild is needed to change them; not directly editable." },
  { q: "AGOL credits are used by which type of operation?", opts: ["Reading a free basemap", "Logging into the org", "Geocoding and storing hosted-layer data", "Saving a web map"], answer: 2, domain: 'D4', exp: "Credits track operations like geocoding (address-to-coords), hosted-layer storage, and some premium content access." },
  { q: "You want a real-time monitoring page with KPI tiles and a map. Which AGOL app fits best?", opts: ["StoryMaps", "Dashboard", "Survey123", "Field Maps"], answer: 1, domain: 'D4', exp: "Dashboards combine KPI cards, charts, and a map driven by a single feature layer — perfect for monitoring." },
  { q: "For mobile data collection by inspectors who need offline maps and forms, use:", opts: ["StoryMaps", "Experience Builder", "Field Maps", "Living Atlas"], answer: 2, domain: 'D4', exp: "Field Maps provides mobile navigation, offline maps, and data collection. Survey123 is for form-heavy collection without map navigation." },
  { q: "Experience Builder in AGOL:", opts: ["Generates Pro projects", "Is a drag-and-drop web app builder that replaced Web AppBuilder", "Is a basemap", "Is a CRS tool"], answer: 1, domain: 'D4', exp: "Experience Builder is the modern AGOL app-building tool. The older Web AppBuilder is being retired." },
  { q: "StoryMaps is best for:", opts: ["Quantitative spatial analysis", "A narrative web piece combining maps, text, photos, and videos", "Hosting feature layers", "Geocoding"], answer: 1, domain: 'D4', exp: "StoryMaps wraps maps in a scrollable narrative — ideal for non-GIS audiences and project storytelling." },
  { q: "Publishing a feature layer from ArcGIS Pro to AGOL requires:", opts: ["Signing into your portal in Pro, then Share As Web Layer", "A Field Maps mobile device", "A new Esri Academy license", "Restarting your computer"], answer: 0, domain: 'D4', exp: "Project tab → Portals → sign in to your AGOL org. Right-click a layer → Share As Web Layer → choose type (Feature, Tile, Vector Tile)." },
  { q: "Living Atlas is:", opts: ["A private set of layers", "A curated public Esri-managed content library", "A premium ArcGIS Pro add-on", "A type of basemap"], answer: 1, domain: 'D4', exp: "Living Atlas is Esri's free curated catalog of basemaps, imagery, demographics, and environmental data — ready to add to any web map." },
  { q: "A Viewer role in AGOL can:", opts: ["Create hosted feature layers", "Publish web apps", "View shared content but not create new items", "Administer the org"], answer: 2, domain: 'D4', exp: "Viewer = read-only. User can create content. Publisher can publish hosted services. Administrator manages the org." },
  { q: "A web map's essential components include:", opts: ["Basemap + operational layers + popups + bookmarks", "A Python script + a CSV", "Only operational layers", "Only a basemap"], answer: 0, domain: 'D4', exp: "A web map combines a basemap, operational layers, popup configurations, and (optionally) bookmarks." },
  { q: "Smart Mapping in AGOL helps with:", opts: ["Auto-licensing", "Choosing defensible symbology defaults based on the data", "Hosting feature layers", "Setting CRS"], answer: 1, domain: 'D1', exp: "Smart Mapping reads the field data type and distribution and suggests a sensible classification + palette starting point." },
  { q: "Item Details that drive discoverability include:", opts: ["Title, Summary, Description, Tags, Terms of Use, Credits", "Only the file size", "OBJECTID", "The CRS only"], answer: 0, domain: 'D4', exp: "Discoverable items get used; bare items collect dust. Fill out Title, Summary, Description, Tags, Terms of Use, Credits, and a Thumbnail." },
  { q: "Your AGOL org URL looks like:", opts: ["www.esri.com/myorg", "yourorg.maps.arcgis.com", "maps.google.com/yourorg", "arcgis.gov/yourorg"], answer: 1, domain: 'D4', exp: "AGOL orgs are subdomain-style URLs: yourorg.maps.arcgis.com." },
  { q: "A file geodatabase (.gdb) is physically:", opts: ["A single ZIP file", "A folder containing many binary files", "A SQLite database", "A network share"], answer: 1, domain: 'D2', exp: "A file geodatabase is a folder of binary files — never edit by hand. Mobile geodatabases (.geodatabase) are single SQLite files." },
  { q: "Mobile geodatabase format is:", opts: ["A folder of binary files", "A single SQLite (.geodatabase) file", "A shapefile bundle", "Always cloud-hosted"], answer: 1, domain: 'D2', exp: "Mobile geodatabases are single SQLite files. Easy to share, embed in mobile apps, and version with git." },
  { q: "An enterprise geodatabase runs in:", opts: ["A web browser only", "SQL Server, Oracle, PostgreSQL, or similar RDBMS", "A Word document", "An MXD"], answer: 1, domain: 'D2', exp: "Enterprise geodatabases live inside an RDBMS and support multi-user editing, versioning, and replication." },
  { q: "A feature dataset inside a geodatabase requires that all contained feature classes share:", opts: ["The same name", "The same CRS", "The same Geometry type", "The same SHAPE_AREA"], answer: 1, domain: 'D2', exp: "All feature classes inside a feature dataset must share one CRS. Required for topology, networks, and some other relational behaviors." },
  { q: "A domain in a geodatabase:", opts: ["Stores attachment files", "Restricts a field to a list of allowed values", "Defines a network", "Is an OGC web service"], answer: 1, domain: 'D2', exp: "A coded-value domain restricts a field's input to a controlled list. Range domains restrict numeric inputs to a min/max." },
  { q: "Subtypes within one feature class let you:", opts: ["Encrypt features", "Apply different defaults, domains, and symbology to subsets of features", "Bypass the CRS", "Run map algebra"], answer: 1, domain: 'D2', exp: "Subtypes carry their own defaults, domains, and symbology. E.g., a Roads feature class with subtypes Highway/Arterial/Local." },
  { q: "Attribute rules fire when:", opts: ["You toggle a layer's visibility", "On insert, update, or delete", "Once per day", "Only at publish time"], answer: 1, domain: 'D2', exp: "Attribute rules are Arcade expressions evaluated during insert/update/delete to validate or auto-populate fields." },
  { q: "Topology rules enforce:", opts: ["Cell-size matching for rasters", "Spatial relationship integrity, e.g., parcels must not overlap", "CRS labels only", "Field-name length"], answer: 1, domain: 'D2', exp: "Topology defines and enforces spatial rules. Violations show in the Error Inspector for correction." },
  { q: "A relationship class links:", opts: ["One basemap to another", "Rows in one table to rows in another by a key field, with referential integrity", "Two layouts together", "A raster to a shapefile"], answer: 1, domain: 'D2', exp: "Relationship classes formalize one-to-one, one-to-many, or many-to-many relations between tables, similar to a database FK." },
  { q: "Metadata in GIS typically includes:", opts: ["Random comments", "Title, abstract, lineage, source, contact, CRS, fields, dates", "Only OBJECTIDs", "Only the file size"], answer: 1, domain: 'D2', exp: "Metadata documents what the data is, where it came from, how to use it, who to contact. ArcGIS Pro's Item Description / ISO style supports this." },
  { q: "ISO 19115 is:", opts: ["A US federal-only standard", "The international standard for geospatial metadata", "A KML extension", "A CSV schema"], answer: 1, domain: 'D2', exp: "ISO 19115 is the international metadata standard. FGDC CSDGM is the (legacy) US federal counterpart." },
  { q: "An APRX file is:", opts: ["A project file format for ArcGIS Pro", "A shapefile sidecar", "A raster format", "A KMZ subtype"], answer: 0, domain: 'D2', exp: "APRX = ArcGIS Pro project. Replaces the legacy MXD (ArcMap project)." },
  { q: "A LYRX file stores:", opts: ["Raw geometry", "Symbology + a reference to a data source, applicable to other layers", "A complete copy of the data", "Tile cache"], answer: 1, domain: 'D1', exp: "A .lyrx is a layer file: symbology plus a pointer to a data source. Apply pre-made symbology in one click." },
  { q: "KMZ vs KML:", opts: ["KMZ is older", "KMZ is a zipped bundle of KML + referenced assets", "KMZ is unsupported by Google Earth", "KMZ requires SQL"], answer: 1, domain: 'D2', exp: "KMZ is a single compressed bundle containing a KML plus referenced images/icons. Easier to share than KML+folder." },
  { q: "Before sharing a GIS layer publicly, you should:", opts: ["Compress the file", "Verify no PII or sensitive locations are encoded in attributes or vertices", "Run Hillshade", "Reproject to Web Mercator"], answer: 1, domain: 'D4', exp: "Public sharing exposes attributes and exact coordinates. Verify no personally identifiable or sensitive locations before publish." },
  { q: "Tags on an AGOL item primarily drive:", opts: ["Symbology", "Discoverability through search", "Sharing level", "CRS"], answer: 1, domain: 'D4', exp: "Tags are keywords used by AGOL search. Include topic, area, and dataset type so people can find your work." }
];;
